```tsx
import { useEffect, useState } from 'react';

function App() {
const [menuOpen, setMenuOpen] = useState(false);

useEffect(() => {
document.body.style.overflow = menuOpen ? 'hidden' : 'auto';
}, [menuOpen]);

useEffect(() => {
const onResize = () => {
if (window.innerWidth > 768) setMenuOpen(false);
};
