{
  "summary": "Create a high-end, premium portfolio system using a dark navy base (#171e19), massive Anton display typography, and an asymmetric layout. The design should feel editorial and cinematic, utilizing generous negative space, smooth CSS transitions, and high-contrast sections.",
  "style": {
    "description": "The style is a mix of Brutalist typography and luxury minimalism. It uses Anton (uppercase, heavy) for all primary headings and Plus Jakarta Sans for clean, legible body text. The primary colors are Navy (#171e19) and Sage (#b7c6c2), supported by Cyan (#d5f4f9) and Taupe (#9f8d8b). Interactions focus on fluid motion (cubic-bezier(0.16, 1, 0.3, 1)) and depth through blurred floating shapes and hover-reveal masks.",
    "prompt": "Apply a design system with the following specifications: Colors: Navy (#171e19), Sage (#b7c6c2), White (#ffffff), Taupe (#9f8d8b), Beige (#d7c5b2), Cyan (#d5f4f9), Soft Blue (#bbe2f5), and Charcoal (#302b2f). Typography: Primary headings in 'Anton', uppercase, tracking-tighter, with font-sizes ranging from 8xl to 18vw. Body text in 'Plus Jakarta Sans' (weights 300, 400, 600). Elements: Use 1px borders, crosshair cursor style, and mix-blend-mode: difference for fixed navigation. Animations: Floating ambient blurs using 120px blur radius, and scroll reveals with transform: translateY(10px) and opacity transition over 1000ms. Hover states: Scale 1.1x on images, circular 'View' buttons with 0.5s cubic-bezier timing."
  },
  "layout_and_structure": {
    "description": "The layout uses a multi-section structure alternating between dark and light backgrounds. It features a full-screen hero, an asymmetric masonry portfolio grid, a featured project section with offset imagery, and a massive footer.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Fixed top bar, full width, 32px-48px padding. Mix-blend-mode: difference. Logo in Anton font, 2xl, tracking-widest. Nav links in small (12px) uppercase tracking-widest font. 'Get in Touch' button with 1px white border, transitioning to white background on hover."
      },
      {
        "part": "Hero Section",
        "prompt": "Full viewport height. Background: Navy (#171e19). Include two floating, blurred circles (Sage and Soft Blue) at 20% opacity. Central text: Anton font, size 18vw, leading 0.85, uppercase. Second line of text uses '.text-outline' (1px Sage stroke, transparent fill). Bottom row: Small uppercase Taupe text (max-width 320px) on the left, bouncing arrow icon in a circular border on the right."
      },
      {
        "part": "Portfolio Grid",
        "prompt": "Background: White (#ffffff). Heading: 'Selected Works' in Anton, 9xl, Navy. Grid: 2-column masonry; even-numbered items should have a 4rem (64px) top margin. Project cards: 3:4 or 4:5 aspect ratio images. On hover: Image scales 1.1x and a Navy 60% overlay appears with a white circular 'View' tag in the center."
      },
      {
        "part": "Featured Asymmetric Section",
        "prompt": "Background: Navy. Two-column layout. Left: Grayscale image with a Cyan decorative background square (#d5f4f9, 20% opacity) offset by -48px. Right: Sage colored 'Anton' label, followed by a 7xl heading and Taupe body text. Include an arrow icon link that shifts +8px right on hover."
      },
      {
        "part": "Capabilities Section",
        "prompt": "Background: Light Gray (#fafafa). Split 12-column grid. Columns 1-4: 'Capabilities' label in Taupe, followed by a list where items have a 40px horizontal line prefix that extends to 64px on hover. Columns 5-12: Large 6xl light-weight heading with italicized accent words in Taupe."
      },
      {
        "part": "Testimonial Carousel",
        "prompt": "Background: Charcoal (#302b2f). Features a decorative quotation mark in the background (Navy, 30rem size, 30% opacity). Main quote: Anton font, 5xl, uppercase. Bio section: 64px colored circular avatar and Anton-style name title."
      },
      {
        "part": "Footer",
        "prompt": "Background: Navy. Massive 'Let's Create' heading in Anton (9xl). Email link in Sage, size 4xl, underlined with 8px offset. Footer bottom: 1px top border (White, 10% opacity), copyright on left, legal links on right, all in 12px uppercase tracking-widest typography."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Hover Reveal Viewport",
      "description": "A circular 'View' badge that appears on image hover.",
      "prompt": "Inside a relative container with overflow-hidden, create an absolute inset-0 overlay with background navy/60 and opacity-0. On parent hover, transition opacity to 100. Center a 96px x 96px white circle containing 'VIEW' in Anton font, 14px, tracking-widest."
    },
    {
      "component": "Ambient Background Orbs",
      "description": "Slow-moving, blurred decorative background elements.",
      "prompt": "Create 384px (w/h) div elements with 120px Gaussian blur. Set opacity to 20%. Apply a CSS animation 'float' moving translateY from 0 to -20px over 6 seconds with ease-in-out infinite loop."
    },
    {
      "component": "Mix-Blend Navigation",
      "description": "Navigation that changes color based on the background it passes over.",
      "prompt": "Apply 'mix-blend-mode: difference' to the fixed nav container. Ensure navigation items are white so they invert to black over white backgrounds and stay white over dark backgrounds."
    }
  ]
}

{
  "summary": "A sophisticated, typography-first creative studio aesthetic featuring a black-and-white color scheme, custom interactive cursor, and smooth, motion-driven layouts.",
  "style": {
    "description": "The style is built on 'Inter' typography with extreme weight and size contrasts. It uses a pure black (#000000) and white (#FFFFFF) palette with neutral gray accents (#525252, #737373) for secondary metadata. Motion is central, utilizing smooth cubic-bezier transitions for reveals and a custom 'difference' blend-mode cursor that scales on interaction. Images are primarily grayscale, transitioning to full color on hover to maintain visual discipline.",
    "prompt": "Apply a Bold Editorial Studio Style. \n- **Color Palette**: Primary background #FFFFFF; Primary text #000000; Secondary text #525252; Accents and borders #000000 at 10% opacity; Footer background #0A0A0A with #FFFFFF text.\n- **Typography**: Primary Font: 'Inter'. \n  - Headlines: font-weight: 700; letter-spacing: -0.05em; line-height: 0.9.\n  - Body: font-weight: 400; letter-spacing: -0.02em; line-height: 1.5.\n  - Mono/Metadata: font-family: 'monospace'; font-size: 14px; text-transform: uppercase; letter-spacing: 0.1em.\n- **Interactions**: \n  - Custom cursor: 32px circle, border: 1px solid black, background: white, mix-blend-mode: difference. Scale by 2.5x on hover. \n  - Image hover: Grayscale (100%) to Grayscale (0%) transition over 700ms with a 1.05x scale transform.\n- **Animations**: \n  - Reveal: Text spans sliding up from translate-y(100%) to (0%) with cubic-bezier(0.16, 1, 0.3, 1) over 1s.\n  - Marquee: Linear infinite scroll at 30s duration, pausing on container hover."
  },
  "layout_and_structure": {
    "description": "The layout follows a spacious, section-based vertical flow. It starts with a massive display hero, followed by a continuous motion marquee, a centered introductory statement, and a balanced two-column project grid. The design concludes with a high-contrast dark footer.",
    "prompts": [
      {
        "part": "Navigation Header",
        "prompt": "Fixed header at the top. Use `mix-blend-mode: difference` for the container to ensure visibility against any background. Left side: lowercase logo 'sd' (font-size: 24px, weight: 700, tracking-tighter). Right side: Menu toggle button using a 'plus' icon. Padding: 24px (6rem)."
      },
      {
        "part": "Hero Section",
        "prompt": "Height: 80vh minimum. Center-aligned. Main headline: font-size: 12vw, weight: 700, tracking-tighter. Implement staggered letter reveal where each character slides up into view. Include a sub-headline: font-size: 24px, color: #525252, margin-top: 32px."
      },
      {
        "part": "Infinite Project Marquee",
        "prompt": "Full-width overflow-hidden section. Items: Vertical cards (aspect-ratio: 5/7). Apply asymmetrical rounded corners to cards (e.g., top-left: 100px, or top-right: 100px + bottom-left: 40px). Animation: Continuous horizontal scroll. Images within should be grayscale by default."
      },
      {
        "part": "Project Grid",
        "prompt": "Two-column grid for desktop, single-column for mobile. Each project item consists of: 1. A 4:3 aspect ratio image container with slight rounding. 2. A hover-triggered overlay (black at 10% opacity). 3. A top-right 'arrow-up-right' icon appearing on hover. 4. Bottom metadata row separated by a 1px #000000/10 border-top, containing a Title (24px), Category, and Year (mono font)."
      },
      {
        "part": "Footer",
        "prompt": "Background: #0A0A0A. Text: #FFFFFF. Four-column grid (on desktop). Column 1-2: Large brand name and short bio. Column 3: 'Socials' list. Column 4: 'Contact' list. Bottom bar: Thin border-top (white at 10% opacity) with copyright and credits in 14px text."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Interactive Difference Cursor",
      "description": "A custom circular cursor that follows the mouse with smooth interpolation and changes appearance based on the underlying color.",
      "prompt": "Create a 32px diameter circle `div` with `position: fixed`, `pointer-events: none`, and `z-index: 9999`. Apply `mix-blend-mode: difference` and `background-color: white`. Use `requestAnimationFrame` to interpolate movement (lerp) for a 'lagging' smooth effect. On hover of 'a' or 'button' tags, use a CSS transition to `transform: scale(2.5)`."
    },
    {
      "component": "Asymmetrical Marquee Cards",
      "description": "Image containers within the marquee that use non-uniform border-radii to create an organic, editorial feel.",
      "prompt": "Style project cards with alternating border-radius patterns: Card A: `border-top-left-radius: 100px`. Card B: `border-top-right-radius: 100px; border-bottom-left-radius: 40px`. Card C: `border-radius: 40px`. This breaks the standard grid monotony."
    }
  ],
  "special_notes": "MUST: Maintain a strict black-and-white palette; any color should only come from project photography. MUST: Use smooth easing for all hover states (minimum 500ms). MUST: Hide the default browser cursor (`cursor: none` on body). DO NOT: Use borders heavier than 1px. DO NOT: Use standard system easing; stick to cubic-bezier(0.16, 1, 0.3, 1) for a premium feel."
}

{
  "summary": "Create a bold, modern B2C SaaS landing page with a high-contrast editorial feel. The design uses aggressive display typography (Anton) paired with clean sans-serif body text (Satoshi), employing a color palette of golden yellow highlights against charcoal and white backgrounds. It features a grid-patterned hero section, high-contrast problem/solution blocks, and a bento-style feature grid.",
  "style": {
    "description": "Brutalist-lite SaaS aesthetic. Key elements include massive display fonts (8xl-9xl), a grid-based background (linear-gradient with 40px spacing), and a strategic use of #ffe17c (golden yellow) for highlights and primary CTAs. Typography pairs the heavy weight of 'Anton' with the sophisticated versatility of 'Satoshi'. Colors include #171e19 (charcoal), #272727 (dark gray), #b7c6c2 (sage), and #ffffff (white).",
    "prompt": "Apply a high-contrast design system. Typography: Use 'Anton' for all primary headlines (uppercase, letter-spacing: normal, line-height: 0.9) and 'Satoshi' for body text (weights 400, 500, 700). Color Palette: Backgrounds should alternate between #ffffff and #171e19. Use #ffe17c as the primary accent color for buttons and text-highlights. Highlights: Use 15-degree rotated rectangle overlays in #ffe17c behind key words in headlines. Borders: Use 1px #171e19/10% opacity for light sections and #b7c6c2/10% for dark sections. Grid Background: Implement a background-size: 40px 40px pattern using linear-gradient(to right, #b7c6c220 1px, transparent 1px). Micro-interactions: Cards should have 300ms cubic-bezier(0.4, 0, 0.2, 1) transitions for transforms and shadows."
  },
  "layout_and_structure": {
    "description": "The layout follows a logical conversion funnel: Hero for immediate value prop, social proof for trust, a high-contrast split-section for problem/solution, a flexible bento grid for features, a numerical step-by-step process, and a high-energy final CTA.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Fixed header (h-20) with #ffffff/90% backdrop-blur. Logo on left in 'Anton' (3xl, uppercase) with a yellow period. Center nav links in 'Satoshi' (sm, font-medium). Right side features a text-only 'Login' link and a pill-shaped button (bg-#171e19, text-white, px-6, rounded-full)."
      },
      {
        "part": "Hero Section",
        "prompt": "Centered layout on a grid pattern background. Feature a badge (caps, tracking-widest, text-xs) with a yellow dot indicator. Headline: 'Anton' (text-6xl to 9xl) with a yellow highlight bar behind the final word. Subheadline: 'Satoshi' (text-lg, text-charcoal/70%, max-w-xl). Waitlist form: side-by-side input (border-charcoal/20, px-6, rounded-lg) and a massive 'Anton' button (bg-yellow, text-xl, px-8)."
      },
