      {/* Content here */}

      <GhostCursor 
        color="#B19EEF"
        trailLength={20}
      />
    </div>
  );
};
```

**Note**: The parent container should have `position: relative` or similar positioning context, as the GhostCursor uses `absolute inset-0`.

